/** Machine translated draft; religious and linguistic review pending. */
internal object DuaBrxDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_travel_full" to DuaText("आबुं दावबायनायनि आरज।", "ऐ अल्लाह, बे दावबायनायाव जों नोंखौ गोथार आरो गोथारथिनि थाखाय आरो नोंखौ गोजोनहोनाय खामानिफोरनि थाखाय सोङो। ऐ अल्लाह, बे दावबायनायखौ जोंनि थाखाय गोरलै खालाम आरो बिनि जानथायखौ बाङाइ खालाम। ऐ अल्लाह, नों दावबायनायाव लोगो आरो नखरनि जोथोनगिरि।", "जेब्ला दावबायनायाव ओंखारो,'सुभानल्लधि सखारा'नि उनाव।", "आबुं सुन्नाह दावबायनाय दुआ।"),
        "dua_return_travel" to DuaText("दावबायनायनिफ्राय फैफिन्दोंमोन।", "जों फैफिनो, उनदाहा लायो, इसोरखौ सिबियो आरो बाख्नायो।", "मोनसे दावबायनायनिफ्राय फैफिन्नायनि उनाव।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा दावबायनायनिफ्राय फैफिन्नायनि समाव बे बाथ्रा बुंदोंमोन।"),
        "dua_farewell_traveller" to DuaText("सासे दावबायारिखौ बिदा होनाय।", "आं नोंनि धोरोम, नोंनि फोथायथि आरो नोंनि खामानिनि फिथाइखौ अल्लाहनो बावनाय।", "जेब्ला सासे दावबायारिखौ बावगारनाय जायो।", "जायखौ अल्लाहनो होनाय जायो बियो माब्लाबाबो खहा जाया।"),
        "dua_entering_town" to DuaText("मोनसे जायगायाव थाद'नाय।", "आं अल्लाहनि आबुं सोदोबफोराव बिथांनि गासै सोरजिलुफोरनि गाज्रिनिफ्राय रैखा नागिरो।", "जेब्ला मोनसे जायगायाव थाद'यो एबा मोनसे गोदान सोहोराव सौफैदोंमोन।", "जेब्लासिम बियो बैनिफ्राय ओंखाराखै अब्लासिम जेबो खहा नङा।"),
        "dua_boarding_ship" to DuaText("जाहाज/गारि गाखोनाय।", "अल्लाहनि मुंजों बिनि नाव जावनाय आरो लंगुर होनाय। थारैनो आंनि इसोरआ क्षमा खालामग्रा, अनजाथाव।", "जाहाज एबा गारि गाखोनाय समाव-पैगंबर नूह (अ. स.) नि सोदोबफोर।", "मोनसे कुरानिक आयना-नूह (ए. एस.) नावनि दुआ।"),
        "dua_istighfar_hayyul_qayyum" to DuaText("हयुल-कयुमजों इस्तिघफार।", "आं अल्लाहनिफ्राय क्षमा नागिरो, जायनि अनगा रावबो इसोर गैया, अराय-जिउगोनां, खांग्रा, आरो आं उनदाहा जानानै बिथांनि फारसे गिदिंबो।", "बावसोमनायनि थाखाय।", "बिथाङा दावहा न'निफ्राय खारलांदोंमोनब्लाबो बिथांनि पापफोरखौ माफ खालामनाय जायो।"),
        "dua_rabbighfir_warham" to DuaText("राबिघफिर वारहम", "आंनि इसोर, बावगार आरो अननाय हो, मानोना नोंनो उनसोरफोरनि गेजेराव साबसिन जाय अननाय दिन्थियो।", "मोनसे कुरानिक दुआ-बावसोमनाय आरो अननायनि थाखाय।", "सूराह अल-मु'मिनुननि जोबथा दफा।"),
        "dua_majlis_kaffarah" to DuaText("कफरात अल-मजलिस", "हे अल्लाह, नोंनो महिमा आरो नोंनो बाख्नायनाय। आं साखि होयो दि नोंनि अनगा रावबो इसोर गैया। आं नोंनि क्षमाखौ नागिरो आरो नोंनि फारसे गोसो बावना थां।", "जेब्ला मोनसे ज'थायनिफ्राय ओंखारो।", "बे ज'थायाव जाय गोरोन्थिबो बुंजादोंमोन बिनि थाखाय मोनसे बावसोमनाय जायो।"),
        "dua_jami_forgiveness" to DuaText("आबुं क्षमा।", "ऐ अल्लाह, आंनि गोरोन्थि, आंनि गियान गैयै, आंनि हाबाफोराव आंनि बांद्राय आरो गासिबो जायखौ नों आंनिख्रुइ साबसिनै मिथियो, बेखौ आंखौ बावगार।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनि मोनसे गुवार दुआ।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बे दुआखौ बानायदोंमोन।"),
        "dua_parents_nuh" to DuaText("बिमा-बिफानि थाखाय नूह (एएस) नि दुआ।", "आंनि इसोर, आंनि बिमा-बिफा, जाय सासे फोथायगिरि महरै आंनि न'आव हाबफैगोन, आरो गासिबो फोथायग्रा हौवाफोर आरो फोथायग्रा आयजोफोरखौ माफ खालाम।", "गावनि बिमा-बिफा आरो फोथायग्राफोरनि थाखाय।", "पैगंबर नूह (अ. स.) नि दुआ।"),
        "dua_shukr_parents" to DuaText("बिमा-बिफा आरो गोथार फिसाफोरनि थाखाय अनथोब।", "आंनि इसोर, नों आंनो आरो आंनि बिमा-बिफाफोरनो होनाय नोंनि अनथोबनि थाखाय आंनो बाखनायनो हो आरो मोजां खामानि मावनो हो जाय नोंखौ गोजोन होयो, आरो आंनि फिसाफोरखौ मोजां खालामो। आं नोंनि फारसे गोसो बावना गोसो बावना थाङो आरो आंबो उनदाहा जानायफोरनि गेजेराव।", "ब्रैजि बोसोर बैसो सौहैनायनि कुरान दुआ।", "गावनि गथ'फोरनि अनथोब, मोजां खामानि आरो गोथारथि-गासैबो मोनसे दुआआव।"),
        "dua_intimacy" to DuaText("जुलि सोमोन्दोनि सिगां", "अल्लाहनि मुंजों। ऐ अल्लाह, शयतानखौ जोंनिफ्राय गोजानाव दोन आरो शयतानखौ नों जोंनो जाय (गथ'सा) होयो बेनिफ्राय गोजानाव दोन।", "जुलि सोमोन्दोनि सिगां।", "जुदि सासे गथ'खौ बिथोन होनाय जायो, अब्ला शैतना माब्लाबाबो बेखौ खहा खालामाखै।"),
        "dua_ibrahim_children_protection" to DuaText("न'आरो गथ'फोरनि रैखाथि।", "आंनि इसोर, बे नोगोरखौ रैखाथि हो आरो आंखौ आरो आंनि गथ'फोरखौ मुसुखाफोरखौ फुजिनायनिफ्राय गोजानाव दोन।", "पैगंबर इब्राहिम (ए. एस.) नि दुआ-नोगोर आरो बिथांनि गथ'फोरनि रैखाथिनि थाखाय।", "तौहिदआव गोख्रों थानायनि थाखाय दुआ।"),
        "dua_drinking_milk" to DuaText("जेब्ला गाइखेर लोंदों", "ऐ अल्लाह, बेखौ जोंनि थाखाय बोर हो आरो बेखौ जोंनो हो।", "जेब्ला गाइखेर लों।", "गाइखेरा जाग्रा आरो लोंनाय मोन्नैनिबो थाखाय थोजासे।"),
        "dua_iftar_host" to DuaText("जेब्ला गुबुनफोरजों गोख्रै सोलियो", "उपबास खालामनाय सुबुंफोरा नोंथांजों लोगोसे गावसोरनि उपबासखौ सिफायनो हायो, गोथार सुबुंफोरा नोंथांनि आदार जानो हायो, आरो फेरेशताफोरा नोंथांनि थाखाय आरज गाबनो हायो।", "सोरबा सासेनि न'आव उपबासखौ सिफायनाय समाव।", "आलासिनि थाखाय पैगंबरनि सलिया अलियाह वसलम दुआ।"),
        "dua_seeing_first_fruit" to DuaText("गिबि फिथाइखौ नाय।", "ऐ अल्लाह, जोंनि फिथाइखौ बोर हो, जोंनि सोहोराव बोर हो, आरो जोंनि सा आरो बुरजा (राहा) खौ बोर हो।", "बोथोरनि गिबि फिथाइखौ नुनानै।", "राहा आरो गावनि सोहोराव बोर होनायनि थाखाय मोनसे दुआ।"),
        "dua_good_news" to DuaText("गोजोनथाव खौरांनि सायाव।", "गासिबो बाख्नायनाया अल्लाहनि थाखाय, जायनि अनथोबजों मोजां जिनिसफोरा आबुं जायो।", "मोजां खौरां मोनब्ला (आरो सिबिनायनि सिबिनायनि हाबाखौ खालाम)।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा गावनि मोजां मोन्नाय माबा मोनसेखौ नुनानै बे बाथ्रा बुंदोंमोन।"),
        "dua_looking_mirror" to DuaText("आयनाआव नाय।", "ऐ अल्लाह, जेरै नों आंनि महरखौ मोजां खालामदोंमोन, आंनि आखुखौबो मोजां खालाम।", "आइनाआव नायब्ला।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बे दुआखौ बानायदोंमोन (बेयो आयनाखौ मुंख'नाय गैयालासेबो गायसनजानाय)।"),
        "dua_rabbana_taqabbal" to DuaText("हाबाफोरखौ नाजावनाय।", "ऐ जोंनि इसोर, जोंनिफ्राय बेखौ आजाव; थारैनो नोंनो खोनानाय, मिन्थिग्रा। आरो जोंनि अननायखौ नाजाव; थारैनो नोंनो अननायनि दारुनगिरि, अनजाथाव।", "काबा लुनाय समाव इब्राहिम आरो इसमाइल (एएस) आ सोंदोंमोन।", "मोनफ्रोमबो मोजां खामानिनि उनाव गनायनायनि थाखाय मोनसे दुआ।"),
        "dua_muawwidhat" to DuaText("मोनथाम कुल (मुआवविधत)", "(सुरा-उल-इखलास) बुंः बियो अल्लाह, सासे। अल्लाह, गावखौ हमथानाय। बियो जोनोम जायाखै आरो जोनोम जायाखै। आरो बिनि रुजुनायाव रावबो गैया।\n\n(सुरा अल-तलाक) बुंः आं फुंनि इसोरनि खाथियाव, बिथाङा जायखौ सोरजिदों बिनि गाज्रिनिफ्राय, गोसोमनि गाज्रिनिफ्राय जेब्ला बेयो थाफायो, बिसोरनि गाज्रिनिफ्राय जायफोरा गान्थिफोराव बिरहोयो आरो रागा जोंनायफोरनि गाज्रिनिफ्राय जेब्ला बियो रागा जोंहोयो।\n\n(सूराह-नास) बुंः आं मानसिफोरनि इसोर, मानसिफोरनि राजा, मानसिफोरनि इसोरनि खाथियाव उनदुनो नागिरो, जाय जिन आरो मानसिफोरनि गेजेराव मानसिफोरनि गोसोफोराव फिसुख्रै खिन्थाबो।", "मोनथाम सूराया सानफ्रोमबो फुं आरो बेलासियाव खेबथाम आरो उन्दुनायनि सिगां आखाइआव बिरनानै देहानि सायाव सुयो।", "बेखौ फुंनि आरो बेलासियाव खेबथाम फरायनाया गासैबोनि रुजुनायाव थोजासे।"),
        "dua_sabr" to DuaText("सहायनाय आरो दिदोमथिनि थाखाय", "जोंनि इसोर, जोंनि सायाव सहायथि हो, जोंनि आथिंखौ गोख्रों खालाम आरो फोथायनो हायै सुबुंफोरनि बेरेखायै जोंनि मदद खालाम।", "गोब्राब आरो नांलाय-मोन्नायनि समाव।", "तालुतनि सान्थ्रिफोरनि दुआ।"),
        "dua_rabbana_innana_amanna" to DuaText("अरनिफ्राय क्षमा आरो रैखाथि।", "जोंनि इसोर, जों फोथायो, बेनिखायनो जोंनि पापफोरखौ क्षमा खालाम आरो जोंफोरखौ अरनि साजानिफ्राय रैखा खालाम।", "मोनसे कुरानिक दुआ।", "इसोरखौ गिनायनि गुनफोरनि गेजेराव मोनसे दुआखौ मुंख'नाय जादों।"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("जोंनि बिथिङाव लामा दिन्थिग्रा (आशाब अल-कहफ)", "जोंनि इसोर, नोंनो जोंनो अननाय हो आरो जोंनि बिथिङाव जोंनि थाखाय थि लामा दिन्थिग्रा थियारि खालाम।", "द'भा अफ द पिपल अफ द द द'वे।", "थिरांथाफोर आरो गोब्राब थासारिफोराव बिथोन होनाय।"),
        "dua_musa_faqir" to DuaText("राहानि थाखाय मुसा (एएस) नि दुआ।", "आंनि इसोर, नों आंनो जाय मोजां हर हर हरगोन, आंनो थारैनो नांगौ।", "राहा आरो मोजां नागिरनाय-माद्यानआव मुसा (एएस) नि दुआ।", "बे दुआनि उनाव, अल्लाहआ मुसाखौ (एएस) न ', खामानि आरो बिसि होयो।"),
        "dua_ayyub" to DuaText("आयुब (एएस) नि दुआआ बेरामाव दं।", "(आंनि इसोर) खहाआ आंखौ सौदों, आरो नोंनो अनजाथावनि गेजेराव बांसिन अनजाथाव।", "बेराम आरो दुखु मोननायाव।", "अल्लाहआ अयूब (ए. एस.) नि दुखुखौ बोखारदोंमोन।"),
        "dua_husn_khatimah" to DuaText("सासे मुसलमान महरै थै (युसुफ ए. एस.)।", "सोरगो आरो बुहुमनि सोरखिगिरि, नों बे मुलुगाव आरो जोबनायाव आंनि रैखाथिगिरि। आंखौ सासे मुसलमान महरै थैनो हो आरो मोजांसाफोरजों लोगो ला।", "मोनसे मोजां जोबनायनि थाखाय मोनसे दुआ।", "पैगंबर युसुफ (ए. एस.) नि दुआ।"),
        "dua_shaitan_hamazat" to DuaText("डेभिलस'व्हिस्पार्सनिफ्राय रिफुज", "आंनि इसोर, आं शादाफोरनि फिसुरनायनिफ्राय नोंनि सिङाव आश्रय नागिरो, आरो आं नोंनि सिङाव आश्रय नागिरो, आंनि इसोर, नङाब्ला बिसोर आंनि खाथियाव फैगोन।", "शेताननि फिस्लायनायफोरनिफ्राय रैखा ला।", "आश्रय नागिरनायनि मोनसे कुरानारि दुआ।"),
        "dua_bad_character" to DuaText("गाज्रि आखुथाइनिफ्राय रैखा खालाम।", "ऐ अल्लाह, आं नोंनाव गाज्रि आखु, गाज्रि खामानि आरो गाज्रि लुबैनायनिफ्राय रैखा नागिरो।", "गाज्रि आखु, खामानि आरो लुबैनायनिफ्राय रैखा ला।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनिफ्राय मोनसे आश्रय।"),
        "dua_zawal_nimah" to DuaText("बोरफोर खोमानिफ्राय रैखा खालाम।", "ऐ अल्लाह, आं नोंनि बोरखौ खोमाना, नों होनाय मोजांनि सोलायनायनिफ्राय, नोंनि हरखाब साजा आरो नोंनि गासिबो दुखुनिफ्राय नोंनि सिङाव शरण नागिरो।", "बोरफोर खोमानाय आरो हरखाब खैफोदनिफ्राय रैखा ला।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनि मोनसे दुआ।"),
        "dua_useless_knowledge" to DuaText("मुलाम्फा गैयै गियाननिफ्राय रैखा खालाम।", "ऐ अल्लाह, आं नोंखौ गियाननिफ्राय आश्रय नागिरो जाय मुलाम्फा जाया, मोनसे गोसो जाय गिया जाय मोनसे जिउमा जाय माब्लाबाबो गोजोन जाया, आरो मोनसे दुआ जाय फिन होजायाखै।", "बाहायजायै गियान आरो अल्लाहखौ गियालासे मोनसे गोसोनिफ्राय रैखा ला।", "पैगंबर सल्लल्लाहु अलैहि वसल्लमनिफ्राय मोनसे आश्रय।"),
        "dua_beneficial_knowledge" to DuaText("मुलामफा गोनां गियान आरो हलाल रिजक।", "ऐ अल्लाह, आं नोंखौ मुलाम्फा गोनां गियान, गोथार राहा आरो गनायजानाय खामानिफोरनि थाखाय सोङो।", "फजरनि आरज गाबनायनि उनाव।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा फजरनि सालामनि उनाव बे बाथ्रा बुंदोंमोन।"),
        "dua_leprosy_diseases" to DuaText("गोब्राब बेरामफोरनिफ्राय रैखा मोननो हानाय", "ऐ अल्लाह, आं नोंनाव बिदुं, पागलामो, खुरिया आरो गासैबो गाज्रि बेरामफोरनिफ्राय आश्रय नागिरो।", "गोब्राब बेरामफोरनिफ्राय रैखा।", "सावस्रिखौ रैखा खालामनो थाखाय मोनसे सुन्नत दुआ।"),
        "dua_fear_people" to DuaText("सुथुर एबा अनागारिफोरनि गिनांगौ।", "ऐ अल्लाह, जों नोंखौ बिसोरनि सिगाङाव दोनगोन आरो बिसोरनि गाज्रिनिफ्राय नोंखौ आश्रय होगोन।", "जेब्ला सोरबा सुबुं एबा सुबुंनि खहा जानायनि गिनांगौ जायो।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमा जेब्ला मोनसे सुबुंखौ गियो अब्ला बे बाथ्राखौ बुंदोंमोन।"),
        "dua_shirk_protection" to DuaText("सिथरनाय सिरकनिफ्राय रैखाथि।", "ऐ अल्लाह, आं मिथिङै नोंजों माबा मोनसेखौ लोगो होनायनिफ्राय नोंनि सिङाव शरण नागिरो, आरो आं मिन्थिना जाय खालामो बिनि थाखाय नोंनिफ्राय क्षमा नागिरो।", "दिन्थिमहरनायनिफ्राय आरो सिरिखौ दोननायनिफ्राय रैखा जाना थानो।", "मोनसे थाम्फैनि थाबायनायनिफ्राय खोबथेनाय सिरका बांसिन खोबथेनाय।"),
        "dua_rain" to DuaText("जेब्ला अखा हायो।", "ऐ अल्लाह, मोनसे मुलाम्फा गोनां अखा हर।", "जेब्ला अखा हायो।", "अखाया मोनसे सम जेब्ला दुआफोरखौ गनायनाय जायो।"),
        "dua_after_rain" to DuaText("अखानि उनाव।", "जोंहा अल्लाहनि अनथोब आरो बिथांनि अननायजों अखा होनाय जादों।", "अखानि उनाव।", "जाय बेखौ बुङो बियो अल्लाहखौ फोथायो।"),
        "dua_istisqa" to DuaText("अखा थाखाय सोंनाय (इस्तिस्का)", "ऐ अल्लाह, जोंनो अखा हर।", "जेब्ला अखा मोना।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा शुक्रबारनि बिबुंथिआव बे दुआखौ खालामदोंमोन आरो अखा हादोंमोन।"),
        "dua_heavy_rain" to DuaText("बांद्राय अखा हानाय।", "ऐ अल्लाह, (बेखौ गोग्लैनो हो) जोंनि सोरगिदिं आरो जोंनि सायाव नङा।", "जेब्ला गोबां अखा हायो।", "जोमैफोरा पैगंबर सल्लल्लाहु अलैहि वस्लमनि दुआनि गेजेरजों खारलांदोंमोन।"),
        "dua_wind" to DuaText("जेब्ला बार बारलाङो।", "ऐ अल्लाह, आं नोंखौ बिनि मोजांनि थाखाय, बिनि सिङाव मोजां आरो जायजों बेखौ दैथायहरदोंमोन बेनि मोजांनि थाखाय सोङो, आरो आं नोंनि सिङाव बेनि गाज्रिनिफ्राय, बिनि सिङाव गाज्रि आरो जायजों बेखौ दैथायहरदोंमोन बिनि गाज्रिनिफ्राय रैखा नागिरो।", "जेब्ला मोनसे गोख्रों बार एबा बारहुंखा बोहैयो।", "पैगम्बर सल्लल्लाहु अलैहि वस्लमा बारहुंखानि समाव बे दुआखौ बानायदोंमोन।"),
        "dua_thunder" to DuaText("थन्डार खोनानाय।", "जायखौ बज्रआ गावनि बाख्नायनायजों बाख्नायो, आरो बिनि गिनांगौजों फेरेशतफोरा बाख्नायजायो, बिनि थाखाय बाख्नायनाय।", "बज्रनि रिंसारनायखौ खोनानाय-अब्दुल्ला इब्न आज-जुबाय़र (रा.) नि सर'।", "सूराह आर-राद (13:13) निफ्राय लानाय।"),
    )
}
